// Branch picker. The list comes from data/libraries.json, regenerated by
// tools/refresh-libraries.mjs straight from the catalogue's own branch selector.

const listNode = document.getElementById('list');
const filterNode = document.getElementById('filter');
const summaryNode = document.getElementById('summary');
const autoCheckNode = document.getElementById('autoCheck');

const libraries = await (await fetch(chrome.runtime.getURL('data/libraries.json'))).json();
const stored = await chrome.storage.sync.get({ preferred: [], autoCheck: true });
const preferred = new Set(stored.preferred);
autoCheckNode.checked = stored.autoCheck;

const networks = libraries.filter(({ parent }) => !parent);
const branchesOf = (code) => libraries.filter(({ parent }) => parent === code);

const matches = (text, needle) => text.toLowerCase().includes(needle);

function render() {
  const needle = filterNode.value.trim().toLowerCase();

  listNode.replaceChildren(...networks.flatMap((network) => {
    const branches = branchesOf(network.code);
    const hits = needle
      ? branches.filter((branch) => matches(branch.name, needle) || matches(network.name, needle))
      : branches;
    if (needle && !hits.length && !matches(network.name, needle)) return [];

    // A network with no branches of its own is selectable directly.
    const entries = branches.length ? hits : [network];
    const chosen = entries.filter(({ code }) => preferred.has(code)).length;

    const details = document.createElement('details');
    details.className = 'rounded border border-slate-200 bg-white';
    details.open = Boolean(needle) || network.code === 'BPM' || chosen > 0;
    details.innerHTML = `
      <summary class="cursor-pointer px-3 py-2 text-sm font-medium">
        ${network.name}
        <span class="ml-1 text-xs font-normal text-slate-500">
          ${chosen ? `${chosen} seleccionada${chosen === 1 ? '' : 's'}` : `${entries.length} ${entries.length === 1 ? 'sede' : 'sedes'}`}
        </span>
      </summary>`;

    const grid = document.createElement('div');
    grid.className = 'grid gap-1 border-t border-slate-100 p-3 sm:grid-cols-2';
    for (const entry of entries) {
      const label = document.createElement('label');
      label.className = 'flex items-center gap-2 text-sm';
      const box = document.createElement('input');
      box.type = 'checkbox';
      box.className = 'size-4';
      box.checked = preferred.has(entry.code);
      box.addEventListener('change', () => {
        box.checked ? preferred.add(entry.code) : preferred.delete(entry.code);
        save();
      });
      label.append(box, document.createTextNode(entry === network ? network.name : entry.name));
      grid.append(label);
    }
    details.append(grid);
    return [details];
  }));

  summaryNode.textContent = preferred.size
    ? `${preferred.size} biblioteca${preferred.size === 1 ? '' : 's'} seleccionada${preferred.size === 1 ? '' : 's'}.`
    : 'Sin bibliotecas seleccionadas: todo lo disponible se mostrará en amarillo.';
}

async function save() {
  await chrome.storage.sync.set({ preferred: [...preferred] });
  render();
}

filterNode.addEventListener('input', render);
autoCheckNode.addEventListener('change', () => {
  chrome.storage.sync.set({ autoCheck: autoCheckNode.checked });
});

render();
